import { test, expect } from '@playwright/test';

/** A role credential from the environment; fails clearly when it is not set. */
function credential(name: string, value: string | undefined): string {
  if (!value) throw new Error(`Environment variable ${name} is not set`);
  return value;
}

test('SCN-0012: Add a task with a non-empty title', async ({ page }) => {
  // Expected (DEMO-004): The /tasks.html page shows a text field labelled Task title with the placeholder Enter a task title and a button labelled Add task.
  // Expected (DEMO-004): When the user enters Check deployment logs and clicks Add task, Check deployment logs appears in the task list.
  await page.goto('/');
  await page.getByRole('textbox', { name: 'Username', exact: true }).fill(credential('RELEASE_DEMO_USERNAME', process.env.RELEASE_DEMO_USERNAME));
  await page.getByRole('textbox', { name: 'Password', exact: true }).fill(credential('RELEASE_DEMO_PASSWORD', process.env.RELEASE_DEMO_PASSWORD));
  await page.getByRole('button', { name: 'Sign in', exact: true }).click();
  await expect(page).toHaveURL('http://localhost:4310/tasks.html');
  await expect(page.getByRole('textbox', { name: 'Task title', exact: true })).toBeVisible();
  await expect(page.getByRole('button', { name: 'Add task', exact: true })).toBeVisible();
  await page.getByRole('textbox', { name: 'Task title', exact: true }).fill('Check deployment logs');
  await page.getByRole('button', { name: 'Add task', exact: true }).click();
  await expect(page.getByText('Check deployment logs', { exact: true })).toBeVisible();
});
